import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

// Book storage backed by a single JSON file.
// Writes go to a temp file and are renamed into place so a crash mid-write
// can't leave a half-written books.json behind.
export function createStore(filePath) {
  let books = null;
  let writing = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      const parsed = JSON.parse(await readFile(filePath, "utf8"));
      books = Array.isArray(parsed.books) ? parsed.books : [];
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      books = [];
    }
    return books;
  }

  function save() {
    // Chain writes so concurrent requests never interleave.
    writing = writing.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${process.pid}.tmp`;
      await writeFile(tmp, JSON.stringify({ books }, null, 2) + "\n");
      await rename(tmp, filePath);
    });
    return writing;
  }

  return {
    async list() {
      return [...(await load())];
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = "" }) {
      await load();
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async markFinished(id) {
      const book = await this.get(id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

