const MAX_BODY = 64 * 1024;
const LIMITS = { title: 300, author: 200, notes: 10000 };

export function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding-left: 1.2rem; }
  li { margin: .3rem 0; }
  .muted { color: #666; }
  form.inline { display: inline; }
  label { display: block; margin-top: .6rem; }
  input, textarea { width: 100%; box-sizing: border-box; font: inherit; padding: .3rem; }
  button { margin-top: .6rem; font: inherit; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: .6rem; border-radius: 4px; }
  .error { color: #b00020; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const link = `<a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a> <span class="muted">by ${escapeHtml(book.author)}</span>`;
  if (book.status === "finished") return `<li>${link}</li>`;
  return `<li>${link}
    <form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
      <button type="submit">Mark finished</button>
    </form></li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="muted">${emptyText}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

function homePage(books, { error = "", values = {} } = {}) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));
  return layout(
    "My books",
    `<h2>Currently reading</h2>
${bookList(reading, "Nothing in progress.")}
<h2>Finished</h2>
${bookList(finished, "No finished books yet.")}
<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
<form method="post" action="/books">
  <label>Title <input name="title" required maxlength="${LIMITS.title}" value="${escapeHtml(values.title ?? "")}"></label>
  <label>Author <input name="author" required maxlength="${LIMITS.author}" value="${escapeHtml(values.author ?? "")}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="${LIMITS.notes}">${escapeHtml(values.notes ?? "")}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

function bookPage(book, url) {
  const status =
    book.status === "finished"
      ? `Finished ${escapeHtml(book.finishedAt?.slice(0, 10) ?? "")}`
      : `Currently reading
    <form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
      <button type="submit">Mark finished</button>
    </form>`;
  return layout(
    book.title,
    `<h2>${escapeHtml(book.title)}</h2>
<p>by ${escapeHtml(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
<p class="muted">Link to share: <a href="${escapeHtml(url)}">${escapeHtml(url)}</a></p>
<p><a href="/">&larr; All books</a></p>`,
  );
}

function send(res, status, html, headers = {}) {
  res.writeHead(status, {
    "Content-Type": "text/html; charset=utf-8",
    "X-Content-Type-Options": "nosniff",
    ...headers,
  });
  res.end(html);
}

function notFound(res) {
  send(res, 404, layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`));
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

export function createApp(store) {
  return async function handle(req, res) {
    try {
      const url = new URL(req.url, `http://${req.headers.host ?? "localhost"}`);
      const path = url.pathname;

      if (path === "/" && req.method === "GET") {
        return send(res, 200, homePage(await store.list()));
      }

      if (path === "/books" && req.method === "POST") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim(),
          author: (form.get("author") ?? "").trim(),
          notes: (form.get("notes") ?? "").trim(),
        };
        let error = "";
        if (!values.title || !values.author) error = "Title and author are required.";
        for (const [field, max] of Object.entries(LIMITS)) {
          if (values[field].length > max) error = `The ${field} is too long (max ${max} characters).`;
        }
        if (error) return send(res, 400, homePage(await store.list(), { error, values }));
        await store.add(values);
        return redirect(res, "/");
      }

      const finish = path.match(/^\/books\/([^/]+)\/finish$/);
      if (finish && req.method === "POST") {
        const book = await store.markFinished(decodeURIComponent(finish[1]));
        if (!book) return notFound(res);
        // Go back to where the button was pressed (home or book page).
        const from = req.headers.referer ? new URL(req.headers.referer, url).pathname : "/";
        return redirect(res, from === `/books/${encodeURIComponent(book.id)}` ? from : "/");
      }

      const show = path.match(/^\/books\/([^/]+)$/);
      if (show && req.method === "GET") {
        const book = await store.get(decodeURIComponent(show[1]));
        if (!book) return notFound(res);
        return send(res, 200, bookPage(book, url.origin + url.pathname));
      }

      if (["/", "/books"].includes(path) || finish || show) {
        return send(res, 405, layout("Not allowed", "<p>Method not allowed.</p>"));
      }
      return send(res, 404, layout("Not found", `<p>Page not found.</p><p><a href="/">&larr; All books</a></p>`));
    } catch (err) {
      if (err.status === 413) return send(res, 413, layout("Too large", "<p>That submission is too large.</p>"));
      console.error(err);
      if (!res.headersSent) send(res, 500, layout("Error", "<p>Something went wrong.</p>"));
    }
  };
}

