import { createServer } from "node:http";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";
import { createStore } from "../src/store.js";

let dir, file, server, base;

async function start() {
  server = createServer(createApp(createStore(file)));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields = {}) =>
  fetch(base + path, { method: "POST", body: new URLSearchParams(fields), redirect: "manual" });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("shows empty lists on first open", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing in progress.");
    expect(html).toContain("No finished books yet.");
  });

  it("adds a book, marks it finished and shows its page", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice." });
    expect(res.status).toBe(303);

    const [book] = JSON.parse(await readFile(file, "utf8")).books;
    expect(book).toMatchObject({ title: "Dune", author: "Frank Herbert", notes: "Spice.", status: "reading" });

    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).toContain("Dune");
    expect(page).toContain("Frank Herbert");
    expect(page).toContain("Spice.");
    expect(page).toContain(`${base}/books/${book.id}`);

    expect((await post(`/books/${book.id}/finish`)).status).toBe(303);
    const home = await (await fetch(base + "/")).text();
    expect(home.indexOf("Dune")).toBeGreaterThan(home.indexOf("<h2>Finished</h2>"));
    expect(home).toContain("Nothing in progress.");
  });

  it("keeps books after a restart", async () => {
    await post("/books", { title: "Emma", author: "Jane Austen" });
    await stop();
    await start();
    expect(await (await fetch(base + "/")).text()).toContain("Emma");
  });

  it("rejects missing fields and escapes HTML", async () => {
    const bad = await post("/books", { title: "", author: "x" });
    expect(bad.status).toBe(400);
    expect(await bad.text()).toContain("Title and author are required.");

    await post("/books", { title: "<script>alert(1)</script>", author: "A" });
    const home = await (await fetch(base + "/")).text();
    expect(home).not.toContain("<script>alert(1)</script>");
    expect(home).toContain("&lt;script&gt;");
  });

  it("returns 404 for unknown books", async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post("/books/nope/finish")).status).toBe(404);
  });
});

